-- German A1: close Unit 3 for review, open Unit 4 and build the first daily-routine lesson.
-- Base content never overwrites generated audio state.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
START TRANSACTION;
SET @de := (SELECT id FROM languages WHERE code='de' LIMIT 1);
SET @level := (SELECT id FROM language_levels WHERE language_id=@de AND cefr_level='A1' LIMIT 1);
SET @unit3 := (SELECT id FROM units WHERE unit_key='de-a1-unit-home-and-nearby' LIMIT 1);
UPDATE units SET status='review',notes='بازبینی پوشش انجام شد. دو درس موجود وسایل پایهٔ اتاق، مالکیت ساده، موقعیت راست و چپ و جلو و عقب و یک ویژگی سادهٔ خانه را پوشش می‌دهند. برای هدف فعلی این واحد شکاف ضروری مستقلی برای درس سوم پیدا نشد؛ توصیف گسترده‌تر مکان بعداً در واحد مسیر و مکان‌های عمومی ادامه پیدا می‌کند.' WHERE id=@unit3 AND status <> 'final';
SET @src := (SELECT id FROM sources WHERE source_key='src-wikibooks-de-lesson-022-daily-routine' LIMIT 1);
SET @unit := (SELECT id FROM units WHERE unit_key='de-a1-unit-daily-routine-work-school' LIMIT 1);
SET @iris := (SELECT id FROM characters WHERE character_key='char-de-iris' LIMIT 1);
SET @paul := (SELECT id FROM characters WHERE character_key='char-de-paul' LIMIT 1);
SET @t_routine := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-comm-work-school-routine' LIMIT 1);
SET @t_routine_sit := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-sit-work-school' LIMIT 1);
SET @t_core := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-ling-core-vocabulary' LIMIT 1);
SET @t_questions := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-ling-questions' LIMIT 1);
SET @t_present := (SELECT id FROM curriculum_targets WHERE language_level_id=@level AND target_key='a1-ling-present-verbs' LIMIT 1);
SET @x_morgens := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-morgens'); SET @x_vormittags := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-vormittags'); SET @x_mittags := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-mittags'); SET @x_nachmittags := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-nachmittags'); SET @x_betrieb := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-betrieb'); SET @x_trinken := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-trinken'); SET @x_machen := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-machen'); SET @x_arbeiten := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-arbeiten'); SET @x_kaffee := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-kaffee'); SET @x_essen := (SELECT id FROM lexemes WHERE lexeme_key='lex-de-essen');
SET @f_trinke := (SELECT id FROM lexeme_forms WHERE lexeme_form_key='lexform-de-trinken-trinke'); SET @f_arbeite := (SELECT id FROM lexeme_forms WHERE lexeme_form_key='lexform-de-arbeiten-arbeite');
SET @lesson := (SELECT id FROM lessons WHERE lesson_key='de-a1-lesson-daily-routine-work');
SET @dialogue := (SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-daily-routine-work');
SET @a1 := (SELECT id FROM activities WHERE activity_key='act-de-a1-daily-routine-conversation'); SET @a2 := (SELECT id FROM activities WHERE activity_key='act-de-a1-dayparts-matching'); SET @a3 := (SELECT id FROM activities WHERE activity_key='act-de-a1-routine-work-choice'); SET @a4 := (SELECT id FROM activities WHERE activity_key='act-de-a1-morning-answer-order');
SET @si_q1 := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-routine-morning-q'); SET @si_a1 := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-routine-morning-coffee'); SET @si_q2 := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-routine-late-morning-q'); SET @si_a2 := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-routine-late-morning-work'); SET @si_tea := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-routine-morning-tea'); SET @si_mid := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-routine-midday-restaurant'); SET @si_aft := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-routine-afternoon-home'); SET @si_morgens := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-word-morgens'); SET @si_vormittags := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-word-vormittags'); SET @si_mittags := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-word-mittags'); SET @si_nachmittags := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-word-nachmittags'); SET @si_betrieb := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-word-betrieb'); SET @si_trinken := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-word-trinken'); SET @si_machen := (SELECT id FROM source_items WHERE item_key='srcitem-de-a1-word-machen');
UPDATE language_levels SET coverage=JSON_SET(coverage,'$.gaps[2]','سه واحد نخست به بازبینی رسیده‌اند؛ واحد چهارم روتین روزانه با نخستین درس منبع‌دار آغاز شده و باید مدرسه و بخش‌های دیگر روز را در ادامه پوشش دهد.'),notes='A1 همچنان در مرحلهٔ ساخت تدریجی است. سه واحد نخست در بازبینی‌اند. واحد چهارم روتین روزانه با درس صبح و پیش از ظهر آغاز شده و مرحلهٔ بعد باید مدرسه و بخش‌های دیگر روز را با منبع قابل‌بازاستفاده پوشش دهد.' WHERE id=@level;
COMMIT;
