INSERT INTO sources(source_key,title,title_fa,organization_or_author,language_code,source_type,url,locator,locator_fa,published_or_updated_at,modernity_status,currency_evidence,license_name,license_url,attribution_text,reuse_status,retrieved_at,notes) VALUES('src-wikibooks-de-lesson-022-daily-routine','Deutschkurs für Anfänger/Lektion 022','روتین روزانه: صبح، کار و بخش‌های روز','Wikibooks contributors','de','course','https://en.wikibooks.org/wiki/Deutschkurs_f%C3%BCr_Anf%C3%A4nger/Lektion_022','Item 936: questions and answers about morning, late morning, midday and afternoon routines, including work, school, meals and going home.','بخش ۹۳۶؛ پرسش و پاسخ دربارهٔ کارهای صبح، پیش از ظهر، ظهر و بعدازظهر، از جمله کار، مدرسه، غذا و برگشتن به خانه.','2026-08-16','maintained_current','صفحهٔ زندهٔ ویکی‌بوکس در ۱۷ سپتامبر ۲۰۲۶ بررسی شد و آخرین ویرایش ثبت‌شدهٔ آن ۱۶ اوت ۲۰۲۶ است. بخش انتخاب‌شده پرسش و پاسخ‌های کوتاه و امروزی دربارهٔ بخش‌های روز، کار، مدرسه و کارهای روزمره دارد.','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/','Wikibooks contributors — Deutschkurs für Anfänger/Lektion 022','reuse_with_attribution','2026-09-17','منبع آغاز واحد روتین روزانه است. در گام نخست فقط پرسش و پاسخ‌های روشن بخش ۹۳۶ دربارهٔ صبح و پیش از ظهر و چند جملهٔ مقایسه‌ای از همان بخش استفاده می‌شوند. متن‌های پیچیده‌تر صفحه برای مراحل بعدی جداگانه ارزیابی خواهند شد.') ON DUPLICATE KEY UPDATE title=VALUES(title),title_fa=VALUES(title_fa),organization_or_author=VALUES(organization_or_author),language_code=VALUES(language_code),source_type=VALUES(source_type),url=VALUES(url),locator=VALUES(locator),locator_fa=VALUES(locator_fa),published_or_updated_at=VALUES(published_or_updated_at),modernity_status=VALUES(modernity_status),currency_evidence=VALUES(currency_evidence),license_name=VALUES(license_name),license_url=VALUES(license_url),attribution_text=VALUES(attribution_text),reuse_status=VALUES(reuse_status),retrieved_at=VALUES(retrieved_at),notes=VALUES(notes);
INSERT INTO units(unit_key,language_level_id,sequence_index,title_fa,grouping_rationale,status,metadata,notes) VALUES('de-a1-unit-daily-routine-work-school',@level,4,'روتین روزانه: کار و مدرسه','پس از معرفی شخص، خانواده و محیط نزدیک، گام بعدی پیوند دادن زمان روز با کارهای معمول است. این واحد ابتدا با پرسش‌های کوتاه دربارهٔ صبح و پیش از ظهر شروع می‌شود و سپس در درس‌های بعدی مدرسه، بعدازظهر و برنامهٔ روزانه را گسترش می‌دهد.','draft',JSON_OBJECT('sourceRefs',JSON_ARRAY('src-wikibooks-de-lesson-022-daily-routine'),'learningTargets',JSON_ARRAY('فهم پرسش و پاسخ کوتاه دربارهٔ کارهای معمول در بخش‌های مختلف روز','اتصال صبح، پیش از ظهر، ظهر و بعدازظهر به کارهای روزمره','فهم اطلاعات ساده دربارهٔ کار یا مدرسه در بافت روتین','دنبال کردن چند کار روزمره در توالی زمانی ساده')),'درس نخست صبح و پیش از ظهر و یک الگوی سادهٔ کار روزانه را پوشش می‌دهد. مرحلهٔ بعد باید مدرسه و بخش‌های دیگر روز را با جمله‌های منبع‌دار گسترش دهد، نه با جمله‌سازی آزاد.') ON DUPLICATE KEY UPDATE sequence_index=VALUES(sequence_index),title_fa=VALUES(title_fa),grouping_rationale=VALUES(grouping_rationale),status=IF(status IN ('review','final'),status,VALUES(status)),metadata=VALUES(metadata),notes=VALUES(notes);
