INSERT INTO lexemes(lexeme_key,language_id,lexeme_type,surface,normalized_surface,lemma,part_of_speech,part_of_speech_fa,cefr_level,translation_fa,usage_note_fa,flashcard_eligible,audio_status) VALUES
('lex-de-morgens',@de,'word','morgens','morgens','morgens','adverb','قید','A1','صبح‌ها / صبح','برای گفتن زمانی از روز که یک کار معمولاً صبح انجام می‌شود استفاده می‌شود.',TRUE,'blocked_until_level_final'),
('lex-de-vormittags',@de,'word','vormittags','vormittags','vormittags','adverb','قید','A1','پیش از ظهرها / پیش از ظهر','برای بیان کارهایی که در بخش پیش از ظهر انجام می‌شوند استفاده می‌شود.',TRUE,'blocked_until_level_final'),
('lex-de-mittags',@de,'word','mittags','mittags','mittags','adverb','قید','A1','ظهرها / ظهر','برای بیان کارهایی که حوالی ظهر انجام می‌شوند استفاده می‌شود.',TRUE,'blocked_until_level_final'),
('lex-de-nachmittags',@de,'word','nachmittags','nachmittags','nachmittags','adverb','قید','A1','بعدازظهرها / بعدازظهر','برای بیان کارهایی که در بعدازظهر انجام می‌شوند استفاده می‌شود.',TRUE,'blocked_until_level_final'),
('lex-de-betrieb',@de,'word','Betrieb','Betrieb','Betrieb','noun','اسم','A1','محل کار / شرکت','در این سطح برای اشارهٔ ساده به محل کار در جملهٔ روزمره استفاده می‌شود.',TRUE,'blocked_until_level_final'),
('lex-de-trinken',@de,'word','trinken','trinken','trinken','verb','فعل','A1','نوشیدن','برای گفتن نوشیدنی‌ای که فرد در یک موقعیت روزمره می‌نوشد استفاده می‌شود.',TRUE,'blocked_until_level_final'),
('lex-de-machen',@de,'word','machen','machen','machen','verb','فعل','A1','انجام دادن / کردن','در پرسش ساده دربارهٔ کاری که فرد در بخشی از روز انجام می‌دهد استفاده می‌شود.',TRUE,'blocked_until_level_final') ON DUPLICATE KEY UPDATE language_id=VALUES(language_id),lexeme_type=VALUES(lexeme_type),surface=VALUES(surface),normalized_surface=VALUES(normalized_surface),lemma=VALUES(lemma),part_of_speech=VALUES(part_of_speech),part_of_speech_fa=VALUES(part_of_speech_fa),cefr_level=VALUES(cefr_level),translation_fa=VALUES(translation_fa),usage_note_fa=VALUES(usage_note_fa),flashcard_eligible=VALUES(flashcard_eligible);
INSERT INTO lexeme_forms(lexeme_form_key,lexeme_id,surface,normalized_surface,form_type,features,origin,review_status,notes) VALUES('lexform-de-trinken-trinke',@x_trinken,'trinke','trinke','inflected',JSON_OBJECT('tense','present','mood','indicative','person','1','number','singular'),'source_attested','approved','در پاسخ منبع‌دار مربوط به صبح، فعل نوشیدن به‌صورت اول‌شخص مفرد زمان حال آمده است.') ON DUPLICATE KEY UPDATE lexeme_id=VALUES(lexeme_id),surface=VALUES(surface),normalized_surface=VALUES(normalized_surface),form_type=VALUES(form_type),features=VALUES(features),origin=VALUES(origin),review_status=VALUES(review_status),notes=VALUES(notes);
INSERT INTO lessons(lesson_key,language_level_id,unit_id,sequence_index,position_in_unit,title_fa,source_title,source_title_fa,status,activity_selection_rationale,sequence_rationale,template_signature,audio_status,notes) VALUES('de-a1-lesson-daily-routine-work',@level,@unit,7,1,'صبح‌ها چه کار می‌کنی؟','Was machen Sie morgens? / Was machen Sie vormittags?','صبح‌ها چه کار می‌کنید؟ / پیش از ظهرها چه کار می‌کنید؟','draft','گفت‌وگو دو بخش نخست روز را در بافت وارد می‌کند؛ سپس چهار جملهٔ منبع‌دار به زمان مناسب وصل می‌شوند، جملهٔ مربوط به کار تشخیص داده می‌شود و در پایان پاسخ صبح بازسازی می‌شود.','درس از تعامل و فهم زمان روز به دسته‌بندی، تمایز معنایی و بازیابی فعال یک پاسخ کوتاه حرکت می‌کند و الگوی فعالیت آن با درس قبلی متفاوت است.','conversation_speaking>matching>multiple_choice>word_order','blocked_until_level_final','درس نخست واحد روتین روزانه؛ متن آلمانی زبان‌آموز فقط از بخش ۹۳۶ منبع ثبت‌شده می‌آید.') ON DUPLICATE KEY UPDATE language_level_id=VALUES(language_level_id),unit_id=VALUES(unit_id),sequence_index=VALUES(sequence_index),position_in_unit=VALUES(position_in_unit),title_fa=VALUES(title_fa),source_title=VALUES(source_title),source_title_fa=VALUES(source_title_fa),status=VALUES(status),activity_selection_rationale=VALUES(activity_selection_rationale),sequence_rationale=VALUES(sequence_rationale),template_signature=VALUES(template_signature),notes=VALUES(notes);
