INSERT INTO dialogues(dialogue_key,language_level_id,scenario,opening_initiator,scene_quality_rationale) VALUES('dlg-de-a1-daily-routine-work',@level,'آیریس از پاول دربارهٔ کارهای معمول صبح و پیش از ظهر می‌پرسد و پاول با دو پاسخ کوتاه دربارهٔ قهوه و کار جواب می‌دهد.','app','دو جفت پرسش و پاسخ بخش ۹۳۶ بدون بازنویسی کنار هم قرار گرفته‌اند و یک گفت‌وگوی طبیعی دربارهٔ دو بخش پیاپی روز می‌سازند.') ON DUPLICATE KEY UPDATE language_level_id=VALUES(language_level_id),scenario=VALUES(scenario),opening_initiator=VALUES(opening_initiator),scene_quality_rationale=VALUES(scene_quality_rationale);
