INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-daily-routine-conversation',@lesson,1,'conversation_speaking','به آیریس بگو صبح و پیش از ظهر معمولاً چه کار می‌کنی.','دو جفت پرسش و پاسخ منبع‌دار، روتین صبح و کار پیش از ظهر را بدون توضیح دستوری سنگین وارد می‌کنند.',@dialogue,JSON_OBJECT('interaction','read_aloud_exchange','openingInitiator','app'),JSON_ARRAY('verbatim_dialogue','persian_translation_added','character_metadata_added'),NULL,'not_required'),
('act-de-a1-dayparts-matching',@lesson,2,'matching','هر جمله را به بخش درست روز وصل کن.','چهار پاسخ کامل از همان بخش منبع، ترتیب زمانی صبح تا بعدازظهر را با کارهای واقعی روزمره پیوند می‌دهند.',NULL,JSON_OBJECT('pairs',JSON_ARRAY(JSON_OBJECT('left','Morgens trinke ich Kaffee.','leftFa','صبح‌ها قهوه می‌نوشم.','right','صبح','rightFa','صبح'),JSON_OBJECT('left','Vormittags arbeite ich im Betrieb.','leftFa','پیش از ظهرها در محل کار کار می‌کنم.','right','پیش از ظهر','rightFa','پیش از ظهر'),JSON_OBJECT('left','Mittags esse ich in einem Restaurant.','leftFa','ظهرها در یک رستوران غذا می‌خورم.','right','ظهر','rightFa','ظهر'),JSON_OBJECT('left','Nachmittags gehe ich nach Hause.','leftFa','بعدازظهرها به خانه می‌روم.','right','بعدازظهر','rightFa','بعدازظهر'))),JSON_ARRAY('source_items_grouped_for_matching','persian_translation_added'),NULL,'not_required'),
('act-de-a1-routine-work-choice',@lesson,3,'multiple_choice','کدام جمله دربارهٔ کار کردن پیش از ظهر است؟','سه پاسخ کامل و منبع‌دار از همان تمرین، کار را از نوشیدن و غذا خوردن جدا می‌کنند.',NULL,JSON_OBJECT('options',JSON_ARRAY(JSON_OBJECT('textTarget','Vormittags arbeite ich im Betrieb.','translationFa','پیش از ظهرها در محل کار کار می‌کنم.','correct',TRUE),JSON_OBJECT('textTarget','Morgens trinke ich Tee.','translationFa','صبح‌ها چای می‌نوشم.','correct',FALSE),JSON_OBJECT('textTarget','Mittags esse ich in einem Restaurant.','translationFa','ظهرها در یک رستوران غذا می‌خورم.','correct',FALSE))),JSON_ARRAY('options_selected_from_source_material','persian_translation_added'),NULL,'not_required'),
('act-de-a1-morning-answer-order',@lesson,4,'word_order','پاسخ مربوط به صبح را دوباره بساز.','پاسخ آغاز گفت‌وگو پس از فهم و تمایز به بازیابی فعال منتقل می‌شود.',NULL,JSON_OBJECT('sourceText','Morgens trinke ich Kaffee.','sourceTextFa','صبح‌ها قهوه می‌نوشم.','tokens',JSON_ARRAY('Morgens','trinke','ich','Kaffee.'),'answer',JSON_ARRAY('Morgens','trinke','ich','Kaffee.')),JSON_ARRAY('sentence_tokenized_for_word_order','persian_translation_added'),NULL,'not_required') ON DUPLICATE KEY UPDATE lesson_id=VALUES(lesson_id),position_index=VALUES(position_index),activity_type=VALUES(activity_type),instruction_fa=VALUES(instruction_fa),selection_reason=VALUES(selection_reason),dialogue_id=VALUES(dialogue_id),payload=VALUES(payload),transformations=VALUES(transformations),audio_text_target=VALUES(audio_text_target);
